import SwiftUI
import CoreLocation
import PhotosUI
import Vision

struct Trip: Codable, Identifiable {
    var id = UUID(); var start: Date; var end: Date; var km: Double; var weather: String; var estimatedStart: Double?; var estimatedEnd: Double?
}
struct Ledger: Codable { var trips: [Trip] = []; var reading: Double?; var readingAt: Int = 0 }
struct Session: Codable { var start: Date; var km: Double = 0; var weather = "Non disponible"; var estimatedStart: Double? }
@MainActor final class Tracker: NSObject, ObservableObject, CLLocationManagerDelegate {
    @Published var ledger = Ledger(); @Published var session: Session?; @Published var status = "Prêt"; @Published var weather = "Non disponible"
    private let gps = CLLocationManager(); private var last: CLLocation?; private var requestedWeather = false
    private let storage = UserDefaults.standard
    var estimate: Double? { ledger.reading.map { $0 + ledger.trips.dropFirst(ledger.readingAt).reduce(0) {$0+$1.km} } }
    var due: Bool { ledger.reading == nil || ledger.trips.count - ledger.readingAt >= 10 }
    override init() { super.init(); if let data = storage.data(forKey:"ledger"), let x = try? JSONDecoder().decode(Ledger.self,from:data) { ledger=x }; gps.delegate=self; gps.desiredAccuracy=kCLLocationAccuracyBest; gps.distanceFilter=5; gps.activityType = .automotiveNavigation; gps.pausesLocationUpdatesAutomatically=false; if let data=storage.data(forKey:"session"), let x=try? JSONDecoder().decode(Session.self,from:data) { session=x; status="Trajet interrompu : reprenez ou terminez" } }
    func save() { storage.set(try? JSONEncoder().encode(ledger),forKey:"ledger"); storage.set(try? JSONEncoder().encode(session),forKey:"session") }
    func start() { if gps.authorizationStatus == .notDetermined { gps.requestWhenInUseAuthorization(); status="Autorisez le GPS puis appuyez sur START"; return }; guard gps.authorizationStatus == .authorizedWhenInUse || gps.authorizationStatus == .authorizedAlways else { status="Activez la localisation dans Réglages"; return }; guard gps.accuracyAuthorization == .fullAccuracy else { status="Activez la localisation précise"; return }; if session == nil { session=Session(start:Date(),estimatedStart:estimate); requestedWeather=false }; last=nil; gps.allowsBackgroundLocationUpdates=true; gps.showsBackgroundLocationIndicator=true; gps.startUpdatingLocation(); status="GPS actif"; save() }
    func stop() { guard let s=session else {return}; gps.stopUpdatingLocation(); last=nil; ledger.trips.append(Trip(start:s.start,end:Date(),km:s.km,weather:s.weather,estimatedStart:s.estimatedStart,estimatedEnd:s.estimatedStart.map{$0+s.km})); session=nil; status="Trajet enregistré"; save() }
    func calibrate(_ value: Double) { guard session == nil, value.isFinite, value>=0 else {return}; ledger.reading=value; ledger.readingAt=ledger.trips.count; save() }
    func locationManager(_ manager: CLLocationManager, didFailWithError error: Error) { status="GPS indisponible : distance potentiellement incomplète" }
    func locationManager(_ manager: CLLocationManager, didUpdateLocations locations: [CLLocation]) { guard session != nil else {return}; for p in locations { guard p.horizontalAccuracy >= 0, p.horizontalAccuracy <= 30, abs(p.timestamp.timeIntervalSinceNow)<30, p.timestamp >= session!.start else {continue}; if let a=last { let dt=p.timestamp.timeIntervalSince(a.timestamp); let d=p.distance(from:a); if dt<=0 {continue}; if dt<60 && d/dt<65 && d>=max(5,min(15,p.horizontalAccuracy/2)) {session!.km += d/1000} }; last=p; if !requestedWeather { requestedWeather=true; let id=session!.start; Task { let result=await Self.fetchWeather(p.coordinate); if session?.start == id {session?.weather=result; save()} else if let i=ledger.trips.firstIndex(where:{$0.start==id}) {ledger.trips[i].weather=result; save()} } } }; save() }
    static func fetchWeather(_ c: CLLocationCoordinate2D) async -> String { let url=URL(string:"https://api.open-meteo.com/v1/forecast?latitude=\(c.latitude)&longitude=\(c.longitude)&current=temperature_2m,weather_code,is_day")!; do { let (data,_)=try await URLSession.shared.data(from:url); let json=try JSONSerialization.jsonObject(with:data) as? [String:Any]; guard let current=json?["current"] as? [String:Any], let temp=current["temperature_2m"] as? Double, let code=current["weather_code"] as? Int else {return "Non disponible"}; let label: String; switch code {case 0: label="Dégagé"; case 1...3: label="Nuageux"; case 45...48: label="Brouillard"; case 51...67,80...82: label="Pluie"; case 71...77,85...86: label="Neige"; case 95...99: label="Orage"; default: label="Code météo \(code)"}; return "\(label), \(temp) °C, \((current["is_day"] as? Int)==1 ? "jour":"nuit")" } catch {return "Non disponible"} }
}
@main struct MyRoadbookApp: App { @StateObject var tracker=Tracker(); var body: some Scene { WindowGroup { ContentView(t:tracker) } } }
struct ContentView: View {
    @ObservedObject var t: Tracker; @State private var photo: PhotosPickerItem?; @State private var reading=""; @State private var recognized=""; @State private var tab=0
    var body: some View { TabView(selection:$tab) {
        NavigationStack { VStack(spacing:24) { Text("Kilomètres d’apprentissage").foregroundStyle(.secondary); Text(t.ledger.trips.reduce(0){$0+$1.km},format:.number.precision(.fractionLength(1))).font(.system(size:48,weight:.bold)); ProgressView(value:min(1500,t.ledger.trips.reduce(0){$0+$1.km}),total:1500); Text("Objectif : 1 500 km"); Spacer(); Button { if t.session != nil && t.status != "Trajet interrompu : reprenez ou terminez" {t.stop()} else {t.start()} } label: { Text(t.session == nil ? "START" : t.status.hasPrefix("Trajet interrompu") ? "REPRENDRE":"STOP").font(.largeTitle.bold()).frame(width:160,height:160).foregroundStyle(.white).background(t.session == nil ? Color.green:Color.red,in:Circle()) }; if t.session != nil && t.status.hasPrefix("Trajet interrompu") {Button("Terminer le trajet"){t.stop()}}; Text("\(t.session?.km ?? 0, specifier:"%.1f") km").font(.title); Text(t.status); Text(t.session?.weather ?? "Météo au démarrage"); Spacer(); if t.due {Button("Relevé du compteur nécessaire"){tab=2}.disabled(t.session != nil)} }.padding().navigationTitle("MyRoadbook") }.tabItem {Label("Accueil",systemImage:"house")}.tag(0)
        NavigationStack { List(t.ledger.trips.reversed()) { trip in VStack(alignment:.leading,spacing:6) {Text(trip.start.formatted(date:.abbreviated,time:.shortened)); Text("\(trip.km,specifier:"%.2f") km · \(Int(trip.end.timeIntervalSince(trip.start)/60)) min").font(.headline); Text(trip.weather); if let a=trip.estimatedStart,let b=trip.estimatedEnd {Text("Compteur estimé : \(a,specifier:"%.1f") → \(b,specifier:"%.1f")").font(.caption)} } } .navigationTitle("Trajets").toolbar {ShareLink(item: csv)} }.tabItem {Label("Trajets",systemImage:"list.bullet")}.tag(1)
        NavigationStack { Form { Section("Compteur") { if let e=t.estimate {Text("Estimation : \(e,specifier:"%.1f") km")}; Text("\(t.ledger.trips.count-t.ledger.readingAt)/10 trajets depuis le relevé"); PhotosPicker("Choisir une photo du tableau de bord",selection:$photo,matching:.images); if !recognized.isEmpty {Text(recognized).font(.caption)}; TextField("Kilométrage réel à confirmer",text:$reading).keyboardType(.decimalPad); Button("Confirmer le relevé") { if let n=Double(reading.replacingOccurrences(of:",",with:".")),n.isFinite,n>=0 {t.calibrate(n); reading=""; recognized=""} }.disabled(t.session != nil || Double(reading.replacingOccurrences(of:",",with:".")) == nil) }; Section {Text("Le relevé corrige uniquement l’estimation future du compteur. Les distances GPS déjà enregistrées restent inchangées.")} }.navigationTitle("Compteur").onChange(of:photo) { _,item in Task { guard let data=try? await item?.loadTransferable(type:Data.self) else {return}; let request=VNRecognizeTextRequest(); request.recognitionLevel = .accurate; do {try VNImageRequestHandler(data:data).perform([request]); let lines=request.results?.compactMap{$0.topCandidates(1).first?.string} ?? []; recognized=lines.joined(separator:" · "); if let match=lines.compactMap({$0.replacingOccurrences(of:" ",with:"").range(of:"^[0-9]{3,8}$",options:.regularExpression) != nil ? $0.replacingOccurrences(of:" ",with:"") : nil}).first {reading=match} } catch {recognized="Lecture impossible : encodez le compteur."} } } }.tabItem {Label("Compteur",systemImage:"gauge")}.tag(2)
    } }
    var csv: String { (["Départ;Arrivée;Distance GPS (km);Météo;Compteur départ estimé;Compteur arrivée estimé"]+t.ledger.trips.map {x in [x.start.ISO8601Format(),x.end.ISO8601Format(),String(x.km),x.weather,x.estimatedStart.map{String($0)} ?? "",x.estimatedEnd.map{String($0)} ?? ""].joined(separator:";")}).joined(separator:"\n") }
}
